INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_9ec79682ff351aa466364a', 'ZM difficulty tuning - Oct 6', 'leonard.hayes@harmonygames.co', '["julia.lawson@harmonygames.co", "robert@harmonygames.co", "arthur.blake@harmonygames.co", "brian.foster@harmonygames.co"]', 'private', E'ZM difficulty tuning - Oct 6\nAgenda\n1. Baseline (Julia): the register from the difficulty baseline card. One sheet with two tabs, Tickets and Rules in force, so we tune from what players have and not from what we remember.\n2. Rage by level (Leonard): one enrage multiplier for every level is too blunt for the early funnel.\n3. Tier 0 versions (Robert): sign-off status per level band.\n4. What 0.3.22 had and what we keep (Robert).\n', '[{"start": 0, "end": 29, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 29, "end": 431, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'b9cca61685', 'f_9ec79682ff351aa466364a', '2025-09-29T18:31:09Z', '2025-09-30T11:04:37Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_f494073fc667097c3c2c6b', 'notes for monday', 'leonard.hayes@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'notes for monday\njulia, three things for the register:\n- leave ZOM-258 off the list. it''s only the icon players see over a monster, it doesn''t change how hard a level plays.\n- arthur is only listening in on monday, view access is enough for him.\n- when you reply to me, also tell me which ticket replaced which.\nfor the session: register first, top to bottom, then the rules tab, then rage by level.', '[{"start": 0, "end": 17, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 17, "end": 399, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'ec74a426a2', 'f_f494073fc667097c3c2c6b', '2025-09-30T15:47:03Z', '2025-09-30T15:51:58Z');
