VALUES ('f_048bf5e69f8e7f1a659a5c', 'slide_cb43e6c53c57', 'el_bf0658751368', 'TEXT_BOX', E'ZM dynamic difficulty - how tiers work\nTiers -2 to +2 per level (ZOM-42); tier 0 is the default version of each level.', NULL, 0, 0, 9144000, 5143500, NULL, 0);
INSERT INTO gslides.slides_pages (presentation_id, object_id, "index", layout, notes)
VALUES ('f_048bf5e69f8e7f1a659a5c', 'slide_7329e157cabf', 1, 'BLANK', NULL);
INSERT INTO gslides.slides_page_elements (presentation_id, page_object_id, object_id, kind, text, placeholder_type, x_emu, y_emu, width_emu, height_emu, table_json, ordinal)
VALUES ('f_048bf5e69f8e7f1a659a5c', 'slide_7329e157cabf', 'el_d0979892e11a', 'TEXT_BOX', E'Starting tier: average CPM over the first 10 levels; 90 or more starts you on tier 1, everyone else on tier 0.\nPromotion: win rate of 80% or more over the last 10 attempts moves you up one tier. On tier -2 one win promotes you.\nDemotion: 4 losses in a row moves you down one tier.', NULL, 0, 0, 9144000, 5143500, NULL, 0);
INSERT INTO gslides.slides_pages (presentation_id, object_id, "index", layout, notes)
