VALUES ('abe096ff0b5d7216efbc889e91d6d13a', '1759229513.774912', 'CAFC495E4006', 'message', 'EMPLOYEE_0016_SLACK_ID', 'yeah three things after status please. who it''s assigned to in linear, the day it got marked done, pacific time (leave it blank if it never got done), and its linear priority. i want to sort by them in the session', 'cec246a6e43158f200fe144f0dd7039c', '1759226461.318204', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T10:51:53.774912Z', '{}');
