VALUES ('6f77386571537f0bd88c959bdc216f94', '1759261706.530914', 'D05HB64NMQU', 'message', 'EMPLOYEE_0038_SLACK_ID', 'julia before monday''s tuning session i want a baseline of the difficulty system from you, not from memory. every difficulty ticket since we started zm and whether players actually have it in the store builds right now, plus the tier and enrage numbers as they are today. the rules for the register are on the difficulty baseline card on the zm roadmap board. reply here when it''s in the folder with how many tickets made the list and how many of each status, and tell me when a new player gets their starting tier', NULL, NULL, 1, 1, '1759262838.442871', false, NULL, '[]', '[]', '[]', '2025-09-30T19:48:26.530914Z', '{}');
