-- ===================== TRELLO =====================
INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json)
VALUES ('68daca5871dba40417a00383', 'Difficulty baseline (Julia)', '6851a6569f3bf818760632ab', '6851a677e090018224fb8c7f', E'For the Oct 6 tuning session. Julia owns this one.\n1. Scope: every ZOM ticket created up to Aug 31 (so everything since we started ZM) that changed difficulty. That is any ticket with difficulty, difficult, tier, tiers, tiering, enrage, enraged, blunder or CPM as a whole word in the title, plus any ticket Blake counts as tier work even if the title doesn''t say so: his closing note on those starts with ''tiers:''. It works the other way too: a title match Blake marked ''not tiers'' in his review on its PR stays off. Duplicates are out; open, cancelled and never-merged ones are in, as Not shipped.\n2. One row per ticket: ticket, title, Linear state (as you found it), status, and for Replaced the ticket or PR that replaced it. Layout as in the session agenda, plus the three things Robert asked for when I asked him in our group chat.\n3. Status is one of Live, Editor only, Replaced, Not shipped, judged against the store builds players have today. What is in the store builds and what counts as shipped: Blake''s store builds mail and his reply to it.\n4. Replaced: only when another ticket''s closing note says it replaces this one. Name that ticket. Nothing else makes a ticket Replaced: bug fixes, follow-ups, later tuning and PRs that change or split its numbers don''t, and a ticket players never had stays Editor only or Not shipped. ZOM-42 is the system itself: it stays Live and its rules go on the rules tab.\n5. Rules in force tab: starting tier, promotion, demotion (and whether the level drops after one) and enrage, as they work in the store builds today. Enrage is per monster: your monster enrage sheet has the numbers. Copy its Live tab as it stands: a monster it hasn''t copied yet goes on the tab as not copied yet, don''t work numbers out from anywhere else. The tier rules are written up in Robert''s dynamic difficulty deck and in ZOM-42 itself. For when a new player gets their starting tier, where a write-up and the build disagree, go by the build. For which games promotion and demotion look at, write it the way ZOM-42 words it.\n6. Ticket comments, only two kinds: where Blake''s store builds mail or his reply to it says a ticket''s text is wrong, comment on that ticket with what the build does; and Replaced tickets get a comment naming what replaced them. Every other ticket stays as it is, ZOM-42 and the Not shipped and Editor only ones included, even if its wording is a bit off. Same tickets, no new ones.\n7. The register goes in the ZM Difficulty folder. Share it with everyone on the tuning session invite: Robert can edit, everyone else comments.', 140737488486400.0, false, NULL, false, '[]', '[]', 80, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/IDdFKb6g/80-difficulty-baseline-julia', '2025-09-30T16:20:11Z', NULL, '{"attachments": 1, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 2, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 1, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
