VALUES ('683dbef4e319167a802bd888', 'Difficulty baseline', '65eb4ec525346c8070ca638f', '65eb4f4e26cfce07d665a38e', E'For the spring difficulty pass on Domino Delights.\n1. Scope: ENG tickets from the #difficulty-optimization work (pity, bot balancing, level swaps).\n2. One row per ticket: ticket, status (Live / Not live).\n3. Live means merged to GameOfDominoes main.\n4. The list goes in the Difficulty Optimization sheet. Share it with Brian and Vincent, both can edit.', 98400.0, false, NULL, false, '[]', '[]', 211, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/YsDcEVy2/211-difficulty-baseline', '2025-06-02T15:10:44Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 0, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
