VALUES ('arthur.blake@harmonygames.co/<CAAMNAwYx-0CiDbK185Gu5MJ7tQOQpotFjqOw79t@mail.gmail.com>', 'arthur.blake@harmonygames.co/1844679607845878519', 'arthur.blake@harmonygames.co', '["SENT"]', 'Hi all, For Monday, so we''re talking about the same thing. The store builds players have today are iOS 0.3.49 (Leonard released it yesterday', 1759223564000, '2025-09-30T09:12:44Z', 1452, 'store builds for monday', 'arthur.blake@harmonygames.co', 'Arthur Blake', '["Julia Lawson <julia.lawson@harmonygames.co>", "Leonard Hayes <leonard.hayes@harmonygames.co>", "Robert <robert@harmonygames.co>", "Brian Foster <brian.foster@harmonygames.co>"]', '[]', '[]', '[]', E'Hi all,
\n
\nFor Monday, so we''re talking about the same thing. The store builds players have today are iOS 0.3.49 (Leonard released it yesterday) and Android 0.3.133. Both were cut from main on Sep 26, and everything difficulty related was merged long before that.
\n
\nBlake', NULL, '[{"name": "Message-ID", "value": "<CAAMNAwYx-0CiDbK185Gu5MJ7tQOQpotFjqOw79t@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 30 Sep 2025 09:12:44 +0000"}, {"name": "Subject", "value": "store builds for monday"}, {"name": "From", "value": "Arthur Blake <arthur.blake@harmonygames.co>"}, {"name": "To", "value": "Julia Lawson <julia.lawson@harmonygames.co>, Leonard Hayes <leonard.hayes@harmonygames.co>, Robert <robert@harmonygames.co>, Brian Foster <brian.foster@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('julia.lawson@harmonygames.co/1844695547248825769', 'julia.lawson@harmonygames.co', 'Two things I left out of the mail this morning. 1. The level editor (Assets/Scripts/LevelEditor and the LevelDesigner', NULL);
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('julia.lawson@harmonygames.co/<CA5_F2rDr1wRIt9hs5OQOh24VwdKeAGryNjbRuXV@mail.gmail.com>', 'julia.lawson@harmonygames.co/1844695547248825769', 'julia.lawson@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Two things I left out of the mail this morning. 1. The level editor (Assets/Scripts/LevelEditor and the LevelDesigner', 1759238765000, '2025-09-30T13:26:05Z', 1544, 'editor stuff and ZOM-199, before Monday', 'arthur.blake@harmonygames.co', 'Arthur Blake', '["Julia Lawson <julia.lawson@harmonygames.co>", "Leonard Hayes <leonard.hayes@harmonygames.co>", "Robert <robert@harmonygames.co>", "Brian Foster <brian.foster@harmonygames.co>"]', '[]', '[]', '[]', E'Two things I left out of the mail this morning.\n\n1. The level editor (Assets/Scripts/LevelEditor and the LevelDesigner panels), anything in an Editor folder and the debug menu (Assets/Scripts/Debug) are stripped before we ship to players on iOS and Android. A ticket whose changes are only level editor or debug tooling never reached players, Done or not.\n\n2. For the rules tab: the starting tier check in the code is cpm > 90, not >= 90, and it runs when a player''s 10th game ends, wins and losses both counted, not after 10 levels cleared. ZOM-199 says >= 90 after the first 10 levels, but the code never changed from the original spec, so 90 exactly stays on tier 0.\n\nBlake', NULL, '[{"name": "Message-ID", "value": "<CA5_F2rDr1wRIt9hs5OQOh24VwdKeAGryNjbRuXV@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 30 Sep 2025 13:26:05 +0000"}, {"name": "Subject", "value": "editor stuff and ZOM-199, before Monday"}, {"name": "From", "value": "Arthur Blake <arthur.blake@harmonygames.co>"}, {"name": "To", "value": "Julia Lawson <julia.lawson@harmonygames.co>, Leonard Hayes <leonard.hayes@harmonygames.co>, Robert <robert@harmonygames.co>, Brian Foster <brian.foster@harmonygames.co>"}, {"name": "In-Reply-To", "value": "<CAAMNAwYx-0CiDbK185Gu5MJ7tQOQpotFjqOw79t@mail.gmail.com>"}, {"name": "References", "value": "<CAAMNAwYx-0CiDbK185Gu5MJ7tQOQpotFjqOw79t@mail.gmail.com>"}]', '<CAAMNAwYx-0CiDbK185Gu5MJ7tQOQpotFjqOw79t@mail.gmail.com>', '<CAAMNAwYx-0CiDbK185Gu5MJ7tQOQpotFjqOw79t@mail.gmail.com>', NULL, '[]');
