INSERT INTO github.github_review_comments (id, pr_id, author_login, body, path, diff_hunk, line, position, commit_id, in_reply_to_id, created_at, seq, pull_request_review_id, side, subject_type)
VALUES ('harmonygames-Games/match3d#265#rc_7', 'harmonygames-Games/match3d#265', 'EMPLOYEE_0025_GITHUB_USERNAME', 'not tiers: this is level settings tooling for the designers, players never see it. leave it out when we list tier work', 'Assets/Scripts/LevelEditor/UI/LevelSettings.cs', E'@@ -113,6 +113,28 @@ public void AddHardDifficultyClicked()\n             AddNewDifficulty(minDifficultyNumber, newDifficultyNumber);\n         }\n \n+public void DeleteDifficultyClicked()\n+{\n+    if (LevelEditorDataStore.Instance.CurrentDifficulty == 0)\n+    {\n+        Debug.LogWarning($"Cannot delete the default difficulty (0). Please select another difficulty first.");\n+        return;\n+    }\n+\n+    var deletedDifficulty = LevelEditorDataStore.Instance.LevelModel.GetDynamicDifficulty(LevelEditorDataStore.Instance.CurrentDifficulty);\n+\n+    LevelEditorDataStore.Instance.LevelModel.DynamicDifficulties =\n+        LevelEditorDataStore.Instance.LevelModel.DynamicDifficulties\n+            .Where(d => d.Difficulty != LevelEditorDataStore.Instance.CurrentDifficulty)\n+            .ToArray();\n+\n+    var baseDifficulty = LevelEditorDataStore.Instance.LevelModel.GetDynamicDifficulty(0);\n+\n+    OnDifficultySelected(baseDifficulty);\n+\n+    GameEventsManager.SafeSendEvent(new LevelDifficultyDeleted(deletedDifficulty));\n+}', 116, NULL, '28cc6fa1b94408ecdae3be20b34dccff7b2abd25', NULL, '2025-07-03T17:50:12Z', 7, 'harmonygames-Games/match3d#265#rev_8', 'RIGHT', 'line');
