VALUES ('harmonygames-Games/match3d#271#rc_1', 'harmonygames-Games/match3d#271', 'EMPLOYEE_0025_GITHUB_USERNAME', 'not tiers: this is a bug fix, enrage was always meant to clear on refill health and push back. no tier version or enrage number changes here. leave it out when we list tier work', 'Assets/Scripts/Monster/MonsterSpawner.cs', E'@@ -523,4 +524,9 @@ public class MonsterSpawner : SingletonMonoBehaviour<MonsterSpawner>\n             AudioManager.Instance.PlayClip(audioClip);\n         }\n     }\n+\n+    public void ResetEnrageCounter()', 528, NULL, '2f1c9a2251dd59ea40b7a64f09231de80ff466ed', NULL, '2025-07-04T01:05:22Z', 1, 'harmonygames-Games/match3d#271#rev_2', 'RIGHT', 'line');
